        "inputs": ["Review comment list"],
        "outputs": ["Annotated document with comments", "Change request list"]
      },
      {
        "id": "A4",
        "name": "Revise Specification Document",
        "actor": "Document Author",
        "system": "Document Repository, Commenting Tool",
        "inputs": ["Annotated document with comments", "Change request list"],
        "outputs": ["Revised specification document"]
      },
      {
        "id": "A5",
        "name": "Confirm Revisions Are Acceptable",
        "actor": "Feature Owner",
        "system": "Document Repository, Change Request Tracker",
        "inputs": ["Revised specification document", "Change request list", "Feature change list"],
        "outputs": ["Revision confirmation decision"]
      },
      {
        "id": "A6",
        "name": "Request Further Revision",
        "actor": "Feature Owner",
        "system": "Change Request Tracker, Commenting Tool",
        "inputs": ["Revised specification document", "Revision confirmation decision (not acceptable)"],
        "outputs": ["Updated change request list"]
      },
      {
        "id": "A7",
        "name": "Give Final Approval Decision",
        "actor": "Approver",
        "system": "Document Repository",
        "inputs": ["Revised specification document (confirmed acceptable)", "Revision confirmation decision"],
        "outputs": ["Approval decision (approved or rejected)"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are all feature changes fully reflected in the specification document?",
